INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7609725, 1231343, 60862, '<td valign="top">Nice work! I enjoy making multi-image long exposures when the subject moves, so congrats on your success!</td>', 'Nice work! I enjoy making multi-image long exposures when the subject moves, so congrats on your success!', '2019-01-22 00:17:38.000000', NULL, 1),
(7609726, 1231399, 60862, '<td valign="top">Fantastic arrangement, and I''m hoping this isn''t a composite; if you managed to pull this off in one shot, it''s easily the winner! Either way, though, it''s a great image to have in your collection.</td>', 'Fantastic arrangement, and I''m hoping this isn''t a composite; if you managed to pull this off in one shot, it''s easily the winner! Either way, though, it''s a great image to have in your collection.', '2019-01-22 00:18:12.000000', NULL, 1),
(7609792, 1231412, 123737, '<td valign="top">https://www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1231412#</td>', 'https://www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1231412#', '2019-01-22 05:29:13.000000', NULL, 1),
(7609793, 1231399, 114285, '<td valign="top">Wow!! Well we need to see no more, this is obviously the winner, Im guessing its that guy from the site council :-)<br/> <br/>Clear 10 and worthy of a magazine entry.<br/> <br/>Oh and oops  I see you spell eclipse wrong, but Im sure you can easily change that :-)</td>', 'Wow!! Well we need to see no more, this is obviously the winner, Im guessing its that guy from the site council :-) Clear 10 and worthy of a magazine entry. Oh and oops  I see you spell eclipse wrong, but Im sure you can easily change that :-)', '2019-01-22 05:50:21.000000', NULL, 1),
