(7609828, 1231340, 3102, '<td valign="top">Congrats on the blue :)</td>', 'Congrats on the blue :)', '2019-01-22 12:46:30.000000', NULL, 1),
(7609830, 1231399, 4517, '<td valign="top">May have been a winner but the rings kill it for me.<br/>Maybe some won`t see them.</td>', 'May have been a winner but the rings kill it for me.Maybe some won`t see them.', '2019-01-22 13:41:12.000000', NULL, 1),
