(7610925, 1231340, 67258, '<td valign="top">An impressive amount of forethought.  Congrats on the ribbon.</td>', 'An impressive amount of forethought.  Congrats on the ribbon.', '2019-01-29 01:23:01.000000', NULL, 0),
(7610927, 1231399, 67258, '<td valign="top">Thoroughly impressive time-lapse image. You should be justifiably proud!  But it is definitely worth re-editing to correct the circles around each moon - wold take it up another notch.<br/><br/><i>Message edited by author 2019-01-29 08:32:56.</i></td>', 'Thoroughly impressive time-lapse image. You should be justifiably proud!  But it is definitely worth re-editing to correct the circles around each moon - wold take it up another notch.', '2019-01-29 01:37:56.000000', '2019-01-29 08:32:56.000000', 0),
